function parseArgs(argv) {
  const args = {};
  for (let index = 0; index < argv.length; index += 1) {
    const item = argv[index];
    if (!item.startsWith("--")) continue;
    const key = item.slice(2);
    const next = argv[index + 1];
    if (!next || next.startsWith("--")) {
      args[key] = true;
    } else {
      args[key] = next;
      index += 1;
    }
  }
  return args;
}



function readJson(file) {
  return JSON.parse(fs.readFileSync(file, "utf8").replace(/^\uFEFF/, ""));
}

function sourceNativeSlideMetadata(workDir) {
  const reportFile = path.join(workDir, "reports", "source-editability-report.json");
  if (!fs.existsSync(reportFile)) return new Map();
  try {
    const report = readJson(reportFile);
    return new Map((report?.slides || [])
      .filter((slide) => slide?.classification === "native-rich" && Number.isInteger(slide?.pageIndex))
      .map((slide) => [slide.pageIndex, slide]));
  } catch {
    // A malformed optional report must not block image-first reconstruction.
    return new Map();
  }
}

function sourceNativeSlideIndexes(workDir) {
  return new Set(sourceNativeSlideMetadata(workDir).keys());
}

function listWorkDirs(root, onlyName = null) {
  return fs.readdirSync(root, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && entry.name.endsWith(".work"))
    .filter((entry) => !onlyName || entry.name === onlyName || entry.name === `${onlyName}.work`)
    .map((entry) => path.join(root, entry.name))
    .sort((a, b) => path.basename(a).localeCompare(path.basename(b)));
}

function sampleUniformPageBackgroundFill(image, fallback = "#FFFFFF") {
  if (!image?.rgba || !Number.isFinite(image.width) || !Number.isFinite(image.height)
    || image.width < 8 || image.height < 8) return fallback;
  const anchors = [
    [0.03, 0.03], [0.5, 0.03], [0.97, 0.03],
    [0.03, 0.5], [0.97, 0.5],
    [0.03, 0.97], [0.5, 0.97], [0.97, 0.97]
  ];
  const samples = anchors.map(([nx, ny]) => {
    const cx = Math.round((image.width - 1) * nx);
    const cy = Math.round((image.height - 1) * ny);
    const colors = [];
    for (let dy = -2; dy <= 2; dy += 1) {
      for (let dx = -2; dx <= 2; dx += 1) {
        colors.push(pixel(image,
          clamp(cx + dx, 0, image.width - 1),
          clamp(cy + dy, 0, image.height - 1)));
      }
    }
    const median = (channel) => colors
      .map((color) => color[channel])
      .sort((a, b) => a - b)[Math.floor(colors.length / 2)];
    return { r: median("r"), g: median("g"), b: median("b"), a: 255 };
  });
  const channelMedian = (channel) => samples
    .map((color) => color[channel])
    .sort((a, b) => a - b)[Math.floor(samples.length / 2)];
  const candidate = {
    r: channelMedian("r"),
    g: channelMedian("g"),
    b: channelMedian("b"),
    a: 255
  };
  const inliers = samples.filter((color) => colorDistance(color, candidate) <= 24);
  return inliers.length >= 6 ? rgbToHex(candidate) : fallback;
}

