function objectifyLayerTextCrops({ page, sourceImage, textBoxes, slideSize, irDir, structuredVisualAtomTextOnly = false }) {
  if (!sourceImage || !page || !Array.isArray(page.images)) return;
  for (const image of page.images) {
    const canObjectify = structuredVisualAtomTextOnly === true
      ? shouldKeepStructuredVisualAtomLayerText(image)
      : shouldObjectifyLayerText(image);
    if (!canObjectify) continue;
    const internalTextBoxes = (textBoxes || []).filter((textBox) =>
      boxCenterInside(textBox.box, image.box)
      && !(shouldKeepFunnelHubDiagramText(image) && shouldKeepFunnelHubTextInResidualCrop(textBox, image))
    );
    if (internalTextBoxes.length < 2) continue;
    const assetFile = resolveAssetPathForIr(image.assetPath, irDir);
    if (!assetFile) continue;
    const masks = internalTextBoxes.map((item) => ptToPxBox(item.box, sourceImage, slideSize, 9));
    const erased = eraseMasks(sourceImage, masks);
    const crop = cropPng(erased, ptToPxBox(image.box, sourceImage, slideSize, 0));
    ensureDir(path.dirname(assetFile));
    writePng(assetFile, crop);
    image.source = {
      ...(image.source || {}),
      residualCrop: true,
      textObjectified: true,
      objectifiedTextBoxes: internalTextBoxes.length,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "local fidelity crop"}; internal text objectified as native textboxes`
    };
  }
}

function shouldObjectifyLayerText(image) {
  const layer = image?.source?.layer || {};
  const layerType = layer.layerType;
  const action = layer.recommendedAction;
  if (shouldDeferNativeRebuildForComponentStrategy(image)) return false;
  if (isProtectedFidelityDiagramDetector(image?.source?.detector)) return false;
  if (shouldKeepFunnelHubDiagramText(image)) return true;
  if (shouldKeepStructuredVisualAtomLayerText(image)) return true;
  if (shouldRemoveHighRiskInternalOverlayText(image)) return false;
  return image?.source?.editable !== true
    && (layerType === "diagram-zone" || layerType === "table-zone")
    && (action === "attempt-native-reconstruction" || action === "split-native-with-residual-crop");
}













function splitErasedResidualCrops({ page, irDir }) {
  if (!page || !Array.isArray(page.images)) return;
  const nextImages = [];
  for (const image of page.images) {
    const replacement = splitErasedResidualCrop(image, irDir);
    if (replacement.length > 0) {
      for (const item of replacement) {
        const decision = resolveResidualDropDecision([
          {
            matched: shouldDropResidualWithNativeVisualAtomPeer(item, page),
            owner: "visual-atom",
            reasonCode: "residual.native-visual-atom-covered"
          },
          {
            matched: shouldDropResidualCoveredByNativeTableShapes(item, page),
            owner: "table-zone",
            reasonCode: "residual.native-table-shapes-covered"
          }
        ]);
        if (decision.dropResidual) {
          recordResidualDropDecision(item, decision);
        } else {
          nextImages.push(item);
        }
      }
    }
    else {
      const decision = resolveResidualDropDecision([
        { matched: shouldDropResidual(image), owner: "native-rebuilder-registry", reasonCode: "residual.owner-claim" },
        { matched: shouldDropResidualWithNativeVisualAtomPeer(image, page), owner: "visual-atom", reasonCode: "residual.native-visual-atom-covered" },
        { matched: shouldDropResidualCoveredByNativeTableShapes(image, page), owner: "table-zone", reasonCode: "residual.native-table-shapes-covered" },
        { matched: shouldDropResidualCoveredByNativeTablePeers(image, page), owner: "table-zone", reasonCode: "residual.native-table-peers-covered" },
        { matched: shouldDropObjectifiedTableZoneResidual(image, page), owner: "table-zone", reasonCode: "residual.objectified-table-zone" }
      ]);
      if (decision.dropResidual) recordResidualDropDecision(image, decision);
      else nextImages.push(image);
    }
  }
  page.images = nextImages;
}

function shouldDropResidualCoveredByNativeTableShapes(image = {}, page = {}) {
  const source = image?.source || {};
  if (String(source.detector || "") !== "split-erased-residual-crop") return false;
  if (shouldPreserveProtectedMinimumUnitCrop(image)) return false;
  const parentImageId = String(source.parentImageId || source.layer?.parentImageId || "");
  if (!parentImageId || !image?.box) return false;
  const expressionForm = String(source.expressionForm || source.layer?.expressionForm || "").toLowerCase();
  const layerType = String(source.layer?.layerType || source.layerType || "").toLowerCase();
  const archetype = String(source.layer?.diagramUnderstanding?.archetype || "").toLowerCase();
  if (!(/table|matrix|grid/.test(expressionForm) || layerType === "table-zone" || /matrix|grid|table/.test(archetype))) return false;
  if (/screenshot|photo|prototype|webpage|ui/.test(`${expressionForm} ${source.reason || ""} ${source.nonEditableReason || ""}`.toLowerCase())) return false;
  const imageArea = Number(image.box.w || 0) * Number(image.box.h || 0);
  if (!Number.isFinite(imageArea) || imageArea <= 0) return false;
  const nativeShapeDetectors = /^(?:table-zone-native-cell-fill|table-zone-native-grid-line|visual-atom-native-(?:right-arrow|rect|chevron|parallelogram|triangle|diamond|connector))$/;
  const overlaps = (page.shapes || [])
    .filter((shape) => shape?.box && String(shape?.source?.layerSourceId || "") === parentImageId)
    .filter((shape) => nativeShapeDetectors.test(String(shape?.source?.detector || "")))
    .map((shape) => ({
      detector: String(shape?.source?.detector || ""),
      area: ptBoxOverlapAreaValue(image.box, shape.box)
    }))
    .filter((item) => item.area > 0);
  if (overlaps.length === 0) return false;
  const maxCoverRatio = Math.max(...overlaps.map((item) => item.area / imageArea));
  const totalCoverRatio = overlaps.reduce((sum, item) => sum + item.area, 0) / imageArea;
  const hasSolidNativeCover = overlaps.some((item) =>
    /^(?:table-zone-native-cell-fill|visual-atom-native-(?:right-arrow|rect|chevron|parallelogram))$/.test(item.detector)
  );
  return hasSolidNativeCover && (maxCoverRatio >= 0.62 || totalCoverRatio >= 0.9);
}

function dropResidualsCoveredByNativeTableShapes(page = {}) {
  if (!Array.isArray(page.images) || page.images.length === 0 || !Array.isArray(page.shapes) || page.shapes.length === 0) {
    return page;
  }
  page.images = page.images.filter((image) => {
    if (!shouldDropResidualCoveredByNativeTableShapes(image, page)) return true;
    if (image.source && typeof image.source === "object") image.source.residualSplitDropped = true;
    return false;
  });
  return page;
}





function createTableMatrixResidualObjects(page = {}, semanticTextBoxes = []) {
  const shapes = [];
  const textBoxes = [];
  const images = Array.isArray(page.images) ? page.images : [];
  const pageForEvidence = {
    ...page,
    textBoxes: [
      ...(page.textBoxes || []),
      ...(Array.isArray(semanticTextBoxes) ? semanticTextBoxes : [])
    ]
  };
  const sourceFor = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    expressionForm: "table-or-matrix",
    expressionSubtype: "residual-native-replacement",
    confidence: 0.78,
    ...extra
  });
  for (const image of images) {
    if (!isTableMatrixResidualImage(image)) continue;
    const prdLabels = tableMatrixResidualPrdLabels(image, pageForEvidence);
    if (prdLabels.length >= 2) {
      prdLabels.forEach((label, index) => {
        const b = label.box || {};
        const box = {
          x: Number(b.x || 0) - 6,
          y: Number(b.y || 0) - 3.5,
          w: Math.max(34, Number(b.w || 0) + 12),
          h: Math.max(18, Number(b.h || 0) + 7)
        };
        shapes.push({
          id: `${image.id || "table-matrix-residual"}-native-prd-pill-${index}`,
          type: "rect",
          box,
          style: { fill: "#F7F7F7", stroke: "#A8A8A8", strokeWidthPt: 1.2, radiusPt: 5 },
          source: sourceFor("table-matrix-residual-native-prd-pill", {
            layerSourceId: String(image.source?.parentImageId || image.source?.layer?.parentImageId || ""),
            residualImageId: image.id,
            text: label.text
          })
        });
      });
      markTableMatrixResidualObjectified(image, "rebuilt PRD pill residuals as native rounded rectangles");
      continue;
    }
    if (isTableMatrixResidualImagePlaceholder(image, pageForEvidence)) {
      const box = image.box || {};
      const x = Number(box.x || 0);
      const y = Number(box.y || 0);
      const w = Number(box.w || 0);
      const h = Number(box.h || 0);
      const gap = Math.max(8, w * 0.08);
      const slotW = (w - gap) / 2;
      const slotH = Math.max(16, h * 0.88);
      const slotY = y + (h - slotH) / 2;
      [0, 1].forEach((index) => {
        const slotX = x + index * (slotW + gap);
        const slot = { x: slotX, y: slotY, w: slotW, h: slotH };
        shapes.push({
          id: `${image.id || "table-matrix-residual"}-native-placeholder-${index}`,
          type: "rect",
          box: slot,
          style: { fill: "#F8F8F8", stroke: "#A8A8A8", strokeWidthPt: 1.25 },
          source: sourceFor("table-matrix-residual-native-image-placeholder", {
            layerSourceId: String(image.source?.parentImageId || image.source?.layer?.parentImageId || ""),
            residualImageId: image.id,
            part: "frame",
            index
          })
        });
        shapes.push({
          id: `${image.id || "table-matrix-residual"}-native-placeholder-diag-a-${index}`,
          type: "line",
          box: { x: slot.x, y: slot.y, w: slot.w, h: slot.h },
          style: { stroke: "#B5B5B5", strokeWidthPt: 1.05, connectorType: "straight" },
          source: sourceFor("table-matrix-residual-native-image-placeholder", {
            layerSourceId: String(image.source?.parentImageId || image.source?.layer?.parentImageId || ""),
            residualImageId: image.id,
            part: "diagonal-a",
            index
          })
        });
        shapes.push({
          id: `${image.id || "table-matrix-residual"}-native-placeholder-diag-b-${index}`,
          type: "line",
          box: { x: slot.x + slot.w, y: slot.y, w: -slot.w, h: slot.h },
          style: { stroke: "#B5B5B5", strokeWidthPt: 1.05, connectorType: "straight" },
          source: sourceFor("table-matrix-residual-native-image-placeholder", {
            layerSourceId: String(image.source?.parentImageId || image.source?.layer?.parentImageId || ""),
            residualImageId: image.id,
            part: "diagonal-b",
            index
          })
        });
      });
      markTableMatrixResidualObjectified(image, "rebuilt image placeholder residual as native frames and diagonals");
    }
  }
  return { shapes, textBoxes };
}



function isTableMatrixResidualImage(image = {}) {
  const source = image.source || {};
  const detector = String(source.detector || "");
  if (!/^(?:split-erased-residual-crop|icon-residual-crop)$/.test(detector)) return false;
  const expressionForm = String(source.expressionForm || source.layer?.expressionForm || "").toLowerCase();
  const expressionSubtype = String(source.expressionSubtype || source.layer?.expressionSubtype || "").toLowerCase();
  const layerType = String(source.layer?.layerType || source.layerType || "").toLowerCase();
  const archetype = String(source.layer?.diagramUnderstanding?.archetype || "").toLowerCase();
  if (!(/table|matrix|grid/.test(`${expressionForm} ${expressionSubtype}`) || layerType === "table-zone" || /matrix|grid|table/.test(archetype))) return false;
  if (shouldPreserveProtectedMinimumUnitCrop(image) && !/table|matrix|grid/.test(`${expressionForm} ${expressionSubtype} ${layerType} ${archetype}`)) return false;
  const box = image.box || {};
  const area = Number(box.w || 0) * Number(box.h || 0);
  return Number.isFinite(area) && area > 0 && area <= 9000;
}

function tableMatrixResidualPrdLabels(image = {}, page = {}) {
  const parentImageId = String(image.source?.parentImageId || image.source?.layer?.parentImageId || "");
  const expanded = expandPtBox(image.box, 18);
  return (page.textBoxes || [])
    .filter((textBox) => textBox?.box && String(textBox?.source?.detector || "") === "table-zone-semantic-native-visible-label")
    .filter((textBox) => !parentImageId || String(textBox?.source?.layerSourceId || "") === parentImageId)
    .filter((textBox) => textBox?.source?.textErasedFromCrop === true)
    .filter((textBox) => /^PRD\s*\d+$/i.test(String(textBox.text || "").trim()))
    .filter((textBox) => {
      if (ptBoxOverlapAreaValue(expanded, textBox.box) > 0) return true;
      const imageCenterY = Number(image.box?.y || 0) + Number(image.box?.h || 0) / 2;
      const textCenterY = Number(textBox.box?.y || 0) + Number(textBox.box?.h || 0) / 2;
      const textCenterX = Number(textBox.box?.x || 0) + Number(textBox.box?.w || 0) / 2;
      return Math.abs(textCenterY - imageCenterY) <= Number(image.box?.h || 0) * 0.75
        && textCenterX >= Number(image.box?.x || 0) - 8
        && textCenterX <= Number(image.box?.x || 0) + Number(image.box?.w || 0) + 8;
    });
}

function isTableMatrixResidualImagePlaceholder(image = {}, page = {}) {
  const box = image.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  if (!Number.isFinite(w) || !Number.isFinite(h) || w <= 0 || h <= 0) return false;
  if (w / h < 2.1 || w / h > 3.8) return false;
  const expanded = expandPtBox(box, 8);
  const nearbyText = (page.textBoxes || []).filter((textBox) =>
    textBox?.box && ptBoxOverlapAreaValue(expanded, textBox.box) > 0
  );
  if (nearbyText.length > 0) return false;
  return true;
}

function markTableMatrixResidualObjectified(image = {}, reason = "rebuilt table/matrix residual as native shapes") {
  image.source = {
    ...(image.source || {}),
    tableMatrixResidualObjectified: true,
    dropErasedResidualAfterNativeRebuild: true,
    preserveResidualCropUnderNativeRebuild: false,
    nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "table/matrix residual crop"}; ${reason}`
  };
}





























function shouldDropResidualWithNativeVisualAtomPeer(image = {}, page = {}) {
  const source = image?.source || {};
  const detector = String(source.detector || "");
  if (!/^(?:icon-residual-crop|visual-atom-residual-crop)$/.test(detector)) return false;
  const atomId = String(source.visualAtomId || "");
  const parentImageId = String(source.parentImageId || "");
  if (!atomId || !parentImageId) return false;
  if (!/^(?:icon-crop-candidate|complex-shape-crop-candidate)$/.test(String(source.visualAtomKind || ""))) return false;
  return (page.shapes || []).some((shape) => {
    const shapeSource = shape?.source || {};
    return String(shapeSource.layerSourceId || "") === parentImageId
      && String(shapeSource.atomId || "") === atomId
      && /^visual-atom-native-(?:right-arrow|chevron|parallelogram|triangle|diamond)$/.test(String(shapeSource.detector || ""));
  });
}

function shouldDropObjectifiedTableZoneResidual(image = {}, page = {}) {
  const source = image?.source || {};
  const detector = String(source.detector || "");
  if (!/^(?:foreground-graphic-underlay-crop|structured-case-graphic-underlay-crop|content-foreground-graphic-underlay-crop)$/.test(detector)) {
    return false;
  }
  if (shouldPreserveProtectedMinimumUnitCrop(image)) return false;
  const expressionForm = String(source.expressionForm || "").toLowerCase();
  if (/screenshot|document|icon|illustration|photo/.test(expressionForm)) return false;
  const layerType = String(source.layer?.layerType || source.layerType || "").toLowerCase();
  const archetype = String(source.layer?.diagramUnderstanding?.archetype || "").toLowerCase();
  const looksStructuredTableZone = layerType === "table-zone"
    || /table|matrix|grid/.test(expressionForm)
    || /matrix|grid|table/.test(archetype)
    || source.tableGridObjectified === true;
  if (!looksStructuredTableZone) return false;
  if (source.visualAtomObjectified !== true || source.tableZoneSemanticTextObjectified !== true) return false;
  const imageId = String(image.id || "");
  const nativeShapes = (page.shapes || []).filter((shape) => {
    const shapeSource = shape?.source || {};
    return String(shapeSource.layerSourceId || "") === imageId
      && /^visual-atom-native-/.test(String(shapeSource.detector || ""));
  }).length;
  const semanticTextBoxes = (page.textBoxes || []).filter((textBox) => {
    const textSource = textBox?.source || {};
    return String(textSource.layerSourceId || "") === imageId
      && textSource.semanticTextSource === true
      && textSource.textErasedFromCrop === true;
  }).length;
  const declaredAtoms = Number(source.objectifiedVisualAtoms || 0);
  const declaredSemanticLabels = Number(source.objectifiedTableZoneSemanticTextBoxes || 0);
  if (Math.max(nativeShapes, declaredAtoms) < 24) return false;
  if (Math.max(semanticTextBoxes, declaredSemanticLabels) < 6) return false;
  const rejected = source.residualSplitRejected || {};
  const splitCouldNotFindIndependentUnits = String(rejected.reason || "") === "too-few-components"
    && String(rejected.tableGridSplitRejected || "") === "too-few-table-grid-components"
    && String(rejected.bandSplitRejected || "") === "too-few-band-components";
  if (!splitCouldNotFindIndependentUnits) return false;
  source.dropErasedResidualAfterNativeRebuild = true;
  source.dropReason = "table-zone residual covered by native visual atoms and semantic text boxes";
  return true;
}





























































































function createStickySketchResidualNativeShapes(page, irDir, slideSize = DEFAULT_SLIDE) {
  if (!page || !Array.isArray(page.images)) return [];
  const shapes = [];
  const keptImages = [];
  for (const image of page.images) {
    const nativeShapes = stickySketchResidualNativeShapesForImage(image, irDir, slideSize);
    if (nativeShapes.length === 0) {
      keptImages.push(image);
      continue;
    }
    shapes.push(...nativeShapes);
    image.source = {
      ...(image.source || {}),
      stickySketchResidualObjectified: true,
      residualSplitDropped: true,
      dropErasedResidualAfterNativeRebuild: true
    };
  }
  if (shapes.length > 0) page.images = keptImages;
  return shapes;
}

function stickySketchResidualNativeShapesForImage(image, irDir, slideSize = DEFAULT_SLIDE) {
  const strokeShapes = stickySketchResidualNativeStrokeShapes(image, irDir, slideSize);
  if (strokeShapes.length > 0) return strokeShapes;
  const shape = stickySketchResidualNativeShape(image, irDir, slideSize);
  return shape ? [shape] : [];
}

function stickySketchResidualNativeShape(image, irDir, slideSize = DEFAULT_SLIDE) {
  const detector = image?.source?.detector;
  if (detector !== "sticky-note-sketch-residual-crop" && !isResidualNativeLineDetector(detector)) return null;
  const box = image.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const lineShape = stickySketchResidualNativeLineShape(image, irDir, slideSize);
  if (lineShape) return lineShape;
  const frameShape = residualNativeExplanationFrameShape(image, irDir, slideSize);
  if (frameShape) return frameShape;
  if (detector !== "sticky-note-sketch-residual-crop") return null;
  if (w < 280 || h < 36 || h > 95 || w / Math.max(1, h) < 5.5) return null;
  const assetFile = resolveAssetPathForIr(image.assetPath, irDir);
  if (!assetFile || !fs.existsSync(assetFile)) return null;
  const residual = readPng(assetFile);
  const color = dominantNonWhiteColor(residual);
  if (!isPaleStickyBannerColor(color)) return null;
  const fill = rgbToHex(color);
  return {
    id: `${image.id || "sticky-sketch"}-native-banner`,
    type: "roundRect",
    box: {
      x: round(box.x + Math.min(4, w * 0.01)),
      y: round(box.y + Math.min(7, h * 0.12)),
      w: round(w - Math.min(8, w * 0.02)),
      h: round(h * 0.62)
    },
    style: {
      fill,
      stroke: "none",
      strokeWidthPt: 0,
      radiusRatio: 0.08,
      shadow: {
        color: "#49C08B",
        alpha: 0.16,
        blurPt: 8,
        distancePt: 2,
        angle: 45
      }
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "sticky-note-sketch-native-banner",
      layerSourceId: image.source?.parentImageId || image.id || null,
      sourceResidualId: image.id || null,
      confidence: 0.82
    }
  };
}

function stickySketchResidualNativeStrokeShapes(image, irDir, slideSize = DEFAULT_SLIDE) {
  if (image?.source?.detector !== "sticky-note-sketch-residual-crop") return [];
  const box = image.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const slideArea = Math.max(1, Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt));
  const areaRatio = w * h / slideArea;
  if (areaRatio > 0.035 || w < 18 || h < 18 || w > 180 || h > 130) return [];
  const assetFile = resolveAssetPathForIr(image.assetPath, irDir);
  if (!assetFile || !fs.existsSync(assetFile)) return [];
  const residual = readPng(assetFile);
  const components = stickySketchStrokeComponents(residual);
  if (components.length < 2 || components.length > 6) return [];
  const totalInk = stickySketchStrokeInkCount(residual);
  const coveredInk = components.reduce((sum, component) => sum + component.pixels, 0);
  if (totalInk < 40 || coveredInk / Math.max(1, totalInk) < 0.86) return [];
  const scaleX = w / Math.max(1, residual.width);
  const scaleY = h / Math.max(1, residual.height);
  const scale = (scaleX + scaleY) / 2;
  const shapes = [];
  const sorted = components.slice().sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
  for (const [index, component] of sorted.entries()) {
    const crop = stickySketchStrokeComponentCrop(residual, component);
    const stats = residualLinearInkStats(crop);
    if (!stats || stats.pixels < 16 || stats.eigenRatio < 7) return [];
    const lineLength = Math.hypot(stats.lineBox.w, stats.lineBox.h);
    if (lineLength < 10 || stats.strokeWidthPx > Math.max(14, lineLength * 0.58)) return [];
    const fullLine = {
      x: component.box.x + stats.lineBox.x,
      y: component.box.y + stats.lineBox.y,
      w: stats.lineBox.w,
      h: stats.lineBox.h
    };
    const axis = Math.abs(fullLine.w) > Math.abs(fullLine.h) * 2.4
      ? "horizontal"
      : Math.abs(fullLine.h) > Math.abs(fullLine.w) * 2.4
        ? "vertical"
        : "diagonal";
    shapes.push({
      id: `${image.id || "sticky-sketch"}-native-stroke-${index}`,
      type: "line",
      box: {
        x: round(box.x + fullLine.x * scaleX),
        y: round(box.y + fullLine.y * scaleY),
        w: round(fullLine.w * scaleX),
        h: round(fullLine.h * scaleY)
      },
      style: {
        stroke: rgbToHex(stats.color || dominantNonWhiteColor(crop) || { r: 120, g: 120, b: 120, a: 255 }),
        strokeWidthPt: Math.max(1, Math.min(5.5, stats.strokeWidthPx * scale)),
        connectorType: "straight"
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "sticky-note-sketch-native-stroke-line",
        layerSourceId: image.source?.parentImageId || image.id || null,
        sourceResidualId: image.id || null,
        sourceResidualDetector: image.source?.detector || null,
        confidence: 0.72,
        axis,
        strokeComponentIndex: index,
        strokeComponentCount: sorted.length,
        eigenRatio: round(stats.eigenRatio)
      }
    });
  }
  return shapes;
}

function isResidualNativeLineDetector(detector) {
  return detector === "process-with-screenshots-residual-crop";
}

function residualNativeExplanationFrameShape(image, irDir, slideSize = DEFAULT_SLIDE) {
  if (image?.source?.detector !== "process-with-screenshots-residual-crop") return null;
  const box = image.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const areaRatio = w * h / Math.max(1, Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt));
  if (w < 260 || h < 40 || h > 95 || areaRatio > 0.08) return null;
  const assetFile = resolveAssetPathForIr(image.assetPath, irDir);
  if (!assetFile || !fs.existsSync(assetFile)) return null;
  const residual = readPng(assetFile);
  const stats = residualFrameStats(residual);
  if (!stats || stats.density < 0.018 || stats.density > 0.13 || stats.edgeRatio < 0.32) return null;
  const color = stats.color || dominantNonWhiteColor(residual);
  if (!color) return null;
  const hsl = rgbToHsl(color);
  if (hsl.s < 0.14 || hsl.l < 0.2 || hsl.l > 0.78) return null;
  return {
    id: `${image.id || "residual"}-native-frame`,
    type: "roundRect",
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(w),
      h: round(h)
    },
    style: {
      fill: "#FFFFFF",
      stroke: rgbToHex(color),
      strokeWidthPt: 1.8,
      radiusRatio: 0.08,
      shadow: {
        color: rgbToHex(color),
        alpha: 0.12,
        blurPt: 4,
        distancePt: 1,
        angle: 45
      }
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "residual-native-explanation-frame",
      layerSourceId: image.source?.parentImageId || image.id || null,
      sourceResidualId: image.id || null,
      sourceResidualDetector: image.source?.detector || null,
      confidence: 0.78
    }
  };
}

function stickySketchResidualNativeLineShape(image, irDir, slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const areaRatio = w * h / Math.max(1, Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt));
  const horizontal = w >= h * 3.2;
  const vertical = h >= w * 3.2;
  const detector = image?.source?.detector;
  const diagonalCandidate = detector === "sticky-note-sketch-residual-crop" && areaRatio <= 0.0065 && Math.max(w, h) >= 45;
  if (((!horizontal && !vertical) || Math.min(w, h) > 24) && !diagonalCandidate) return null;
  if ((horizontal || vertical) && (areaRatio > 0.01 || Math.max(w, h) < 28 || Math.min(w, h) > 24)) return null;
  const assetFile = resolveAssetPathForIr(image.assetPath, irDir);
  if (!assetFile || !fs.existsSync(assetFile)) return null;
  const residual = readPng(assetFile);
  if (!horizontal && !vertical) {
    return stickySketchResidualNativeDiagonalLineShape(image, residual, slideSize);
  }
  const ink = residualInkStats(residual);
  if (!ink || ink.pixels < 12 || ink.density < 0.08) return null;
  const inkAspect = ink.box.w / Math.max(1, ink.box.h);
  if (horizontal && inkAspect < 2.2) return null;
  if (vertical && inkAspect > 0.45) return null;
  const color = dominantNonWhiteColor(residual) || { r: 120, g: 120, b: 120, a: 255 };
  const strokeWidthPt = Math.max(1, Math.min(4, horizontal ? h * Math.min(0.45, ink.box.h / Math.max(1, residual.height)) : w * Math.min(0.45, ink.box.w / Math.max(1, residual.width))));
  const nativeDetector = detector === "sticky-note-sketch-residual-crop"
    ? "sticky-note-sketch-native-line"
    : "residual-native-line";
  return {
    id: `${image.id || "sticky-sketch"}-native-line`,
    type: "line",
    box: horizontal
      ? {
        x: round(box.x + (ink.box.x / residual.width) * w),
        y: round(box.y + ((ink.box.y + ink.box.h / 2) / residual.height) * h),
        w: round((ink.box.w / residual.width) * w),
        h: 0
      }
      : {
        x: round(box.x + ((ink.box.x + ink.box.w / 2) / residual.width) * w),
        y: round(box.y + (ink.box.y / residual.height) * h),
        w: 0,
        h: round((ink.box.h / residual.height) * h)
      },
    style: {
      stroke: rgbToHex(color),
      strokeWidthPt,
      connectorType: "straight"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: nativeDetector,
      layerSourceId: image.source?.parentImageId || image.id || null,
      sourceResidualId: image.id || null,
      sourceResidualDetector: detector || null,
      confidence: 0.76,
      axis: horizontal ? "horizontal" : "vertical"
    }
  };
}

function stickySketchResidualNativeDiagonalLineShape(image, residual, slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const stats = residualLinearInkStats(residual);
  if (!stats || stats.pixels < 50 || stats.density < 0.05 || stats.density > 0.55 || stats.eigenRatio < 18) return null;
  if (Math.abs(stats.lineBox.w) < 6 || Math.abs(stats.lineBox.h) < 18) return null;
  const color = stats.color || dominantNonWhiteColor(residual) || { r: 120, g: 120, b: 120, a: 255 };
  return {
    id: `${image.id || "sticky-sketch"}-native-diagonal-line`,
    type: "line",
    box: {
      x: round(box.x + (stats.lineBox.x / residual.width) * w),
      y: round(box.y + (stats.lineBox.y / residual.height) * h),
      w: round((stats.lineBox.w / residual.width) * w),
      h: round((stats.lineBox.h / residual.height) * h)
    },
    style: {
      stroke: rgbToHex(color),
      strokeWidthPt: Math.max(1, Math.min(4, stats.strokeWidthPx / Math.max(1, residual.width) * w)),
      connectorType: "straight"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "sticky-note-sketch-native-diagonal-line",
      layerSourceId: image.source?.parentImageId || image.id || null,
      sourceResidualId: image.id || null,
      sourceResidualDetector: image.source?.detector || null,
      confidence: 0.74,
      axis: "diagonal",
      eigenRatio: round(stats.eigenRatio)
    }
  };
}

function residualFrameStats(image) {
  let ink = 0;
  let edge = 0;
  const edgeColors = [];
  const edgeBand = Math.max(6, Math.round(Math.min(image.width, image.height) * 0.05));
  for (let y = 0; y < image.height; y += 1) {
    for (let x = 0; x < image.width; x += 1) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      const hsl = rgbToHsl(color);
      if (isNearWhiteFrameBackground(color, hsl)) continue;
      ink += 1;
      const onEdge = x < edgeBand || y < edgeBand || x >= image.width - edgeBand || y >= image.height - edgeBand;
      if (onEdge) {
        edge += 1;
        if (hsl.s >= 0.12 && hsl.l >= 0.18 && hsl.l <= 0.82) edgeColors.push(color);
      }
    }
  }
  if (ink < 20) return null;
  return {
    density: ink / Math.max(1, image.width * image.height),
    edgeRatio: edge / Math.max(1, ink),
    color: averageColor(edgeColors)
  };
}

function residualLinearInkStats(image) {
  const points = [];
  const colors = [];
  for (let y = 0; y < image.height; y += 1) {
    for (let x = 0; x < image.width; x += 1) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      const hsl = rgbToHsl(color);
      if (isNearWhiteFrameBackground(color, hsl)) continue;
      points.push({ x, y });
      if (hsl.s >= 0.05 && hsl.l >= 0.12 && hsl.l <= 0.86) colors.push(color);
    }
  }
  if (points.length < 12) return null;
  let sx = 0;
  let sy = 0;
  for (const point of points) {
    sx += point.x;
    sy += point.y;
  }
  const mx = sx / points.length;
  const my = sy / points.length;
  let xx = 0;
  let yy = 0;
  let xy = 0;
  for (const point of points) {
    const dx = point.x - mx;
    const dy = point.y - my;
    xx += dx * dx;
    yy += dy * dy;
    xy += dx * dy;
  }
  xx /= points.length;
  yy /= points.length;
  xy /= points.length;
  const trace = xx + yy;
  const determinant = xx * yy - xy * xy;
  const discriminant = Math.sqrt(Math.max(0, trace * trace / 4 - determinant));
  const eigen1 = trace / 2 + discriminant;
  const eigen2 = trace / 2 - discriminant;
  const angle = 0.5 * Math.atan2(2 * xy, xx - yy);
  const ux = Math.cos(angle);
  const uy = Math.sin(angle);
  let minT = Infinity;
  let maxT = -Infinity;
  let maxPerp = 0;
  for (const point of points) {
    const dx = point.x - mx;
    const dy = point.y - my;
    const t = dx * ux + dy * uy;
    const p = Math.abs(-dx * uy + dy * ux);
    minT = Math.min(minT, t);
    maxT = Math.max(maxT, t);
    maxPerp = Math.max(maxPerp, p);
  }
  const x1 = mx + minT * ux;
  const y1 = my + minT * uy;
  const x2 = mx + maxT * ux;
  const y2 = my + maxT * uy;
  return {
    pixels: points.length,
    density: points.length / Math.max(1, image.width * image.height),
    eigenRatio: eigen1 / Math.max(1, eigen2),
    strokeWidthPx: Math.max(1, maxPerp * 2),
    color: averageColor(colors),
    lineBox: {
      x: x1,
      y: y1,
      w: x2 - x1,
      h: y2 - y1
    }
  };
}

function isNearWhiteFrameBackground(color, hsl = rgbToHsl(color)) {
  const max = Math.max(color.r, color.g, color.b);
  const min = Math.min(color.r, color.g, color.b);
  return (max > 244 && max - min < 28) || (hsl.l > 0.9 && hsl.s < 0.36);
}

function residualInkStats(image) {
  let minX = image.width;
  let minY = image.height;
  let maxX = -1;
  let maxY = -1;
  let pixels = 0;
  for (let y = 0; y < image.height; y += 1) {
    for (let x = 0; x < image.width; x += 1) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      const hsl = rgbToHsl(color);
      if (hsl.l > 0.96 && hsl.s < 0.12) continue;
      pixels += 1;
      minX = Math.min(minX, x);
      minY = Math.min(minY, y);
      maxX = Math.max(maxX, x);
      maxY = Math.max(maxY, y);
    }
  }
  if (maxX < minX || maxY < minY) return null;
  const box = { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
  return {
    box,
    pixels,
    density: pixels / Math.max(1, box.w * box.h)
  };
}

function dominantNonWhiteColor(image) {
  const buckets = new Map();
  for (let y = 0; y < image.height; y += 3) {
    for (let x = 0; x < image.width; x += 3) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      const hsl = rgbToHsl(color);
      if (hsl.l > 0.965 && hsl.s < 0.10) continue;
      const key = `${Math.round(color.r / 12)},${Math.round(color.g / 12)},${Math.round(color.b / 12)}`;
      const entry = buckets.get(key) || { count: 0, r: 0, g: 0, b: 0 };
      entry.count += 1;
      entry.r += color.r;
      entry.g += color.g;
      entry.b += color.b;
      buckets.set(key, entry);
    }
  }
  const dominant = [...buckets.values()].sort((a, b) => b.count - a.count)[0];
  if (!dominant || dominant.count < 6) return null;
  return {
    r: Math.round(dominant.r / dominant.count),
    g: Math.round(dominant.g / dominant.count),
    b: Math.round(dominant.b / dominant.count),
    a: 255
  };
}

function isPaleStickyBannerColor(color) {
  if (!color) return false;
  const hsl = rgbToHsl(color);
  return hsl.h >= 170 && hsl.h <= 215 && hsl.s >= 0.12 && hsl.s <= 0.95 && hsl.l >= 0.74 && hsl.l <= 0.95;
}

function stickySketchStrokeComponents(image) {
  const visited = new Uint8Array(image.width * image.height);
  const components = [];
  for (let y = 0; y < image.height; y += 1) {
    for (let x = 0; x < image.width; x += 1) {
      const startIdx = y * image.width + x;
      if (visited[startIdx] || !isStickySketchStrokePixel(pixel(image, x, y))) continue;
      const queue = [[x, y]];
      visited[startIdx] = 1;
      let qi = 0;
      let minX = x;
      let maxX = x;
      let minY = y;
      let maxY = y;
      let count = 0;
      const points = [];
      while (qi < queue.length && count < 80000) {
        const [cx, cy] = queue[qi++];
        count += 1;
        points.push({ x: cx, y: cy });
        minX = Math.min(minX, cx);
        maxX = Math.max(maxX, cx);
        minY = Math.min(minY, cy);
        maxY = Math.max(maxY, cy);
        for (let oy = -1; oy <= 1; oy += 1) {
          for (let ox = -1; ox <= 1; ox += 1) {
            if (ox === 0 && oy === 0) continue;
            const nx = cx + ox;
            const ny = cy + oy;
            if (nx < 0 || ny < 0 || nx >= image.width || ny >= image.height) continue;
            const idx = ny * image.width + nx;
            if (visited[idx] || !isStickySketchStrokePixel(pixel(image, nx, ny))) continue;
            visited[idx] = 1;
            queue.push([nx, ny]);
          }
        }
      }
      if (count < 14) continue;
      const box = expandPxBox({ x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 }, image, 1);
      const areaRatio = box.w * box.h / Math.max(1, image.width * image.height);
      if (areaRatio < 0.001 || areaRatio > 0.98) continue;
      components.push({ box, pixels: count, points });
    }
  }
  return components.sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
}

function stickySketchStrokeComponentCrop(image, component) {
  const box = component?.box || { x: 0, y: 0, w: image.width, h: image.height };
  const crop = {
    width: Math.max(1, Number(box.w || 1)),
    height: Math.max(1, Number(box.h || 1)),
    rgba: Buffer.alloc(Math.max(1, Number(box.w || 1)) * Math.max(1, Number(box.h || 1)) * 4, 255)
  };
  for (let offset = 3; offset < crop.rgba.length; offset += 4) crop.rgba[offset] = 0;
  const points = Array.isArray(component?.points) ? component.points : [];
  for (const point of points) {
    const x = point.x - box.x;
    const y = point.y - box.y;
    if (x < 0 || y < 0 || x >= crop.width || y >= crop.height) continue;
    const sourceOffset = (point.y * image.width + point.x) * 4;
    const targetOffset = (y * crop.width + x) * 4;
    crop.rgba[targetOffset] = image.rgba[sourceOffset];
    crop.rgba[targetOffset + 1] = image.rgba[sourceOffset + 1];
    crop.rgba[targetOffset + 2] = image.rgba[sourceOffset + 2];
    crop.rgba[targetOffset + 3] = image.rgba[sourceOffset + 3];
  }
  return crop;
}

function stickySketchStrokeInkCount(image) {
  let count = 0;
  for (let y = 0; y < image.height; y += 1) {
    for (let x = 0; x < image.width; x += 1) {
      if (isStickySketchStrokePixel(pixel(image, x, y))) count += 1;
    }
  }
  return count;
}

function isStickySketchStrokePixel(color) {
  if (color.a < 64) return false;
  const hsl = rgbToHsl(color);
  if (isNearWhiteFrameBackground(color, hsl)) return false;
  const max = Math.max(color.r, color.g, color.b);
  const min = Math.min(color.r, color.g, color.b);
  const neutralStroke = max < 235 && max - min < 36;
  return hsl.l < 0.88 || hsl.s > 0.18 || neutralStroke;
}

















































function createPrototypeGenerationLoopPictorialCrops({ sourceImage, regions = [], slideSize = DEFAULT_SLIDE, assetDir, irDir, deckName, pageIndex, source = {} } = {}) {
  if (!sourceImage || !assetDir || !Array.isArray(regions)) return [];
  ensureDir(assetDir);
  return regions.filter((region) => region?.box?.w >= 8 && region?.box?.h >= 8).map((region, index) => {
    const box = clampPtBoxToSlide(region.box, slideSize);
    const base = safeIdentifier(`${deckName || "deck"}-p${String(Number(pageIndex || 0) + 1).padStart(2, "0")}-prototype-loop-${region.key || index}`, "prototype-loop-atom");
    const file = path.join(assetDir, `${base}.png`);
    writePng(file, cropPng(sourceImage, ptToPxBox(box, sourceImage, slideSize, 0)));
    return {
      id: `prototype-generation-loop-pictorial-${region.key || index}-${pageIndex || 0}`,
      type: "fidelity-crop",
      assetPath: path.relative(irDir || assetDir, file).replace(/\\/g, "/"),
      box,
      source: reclassifyImageSource(source, box, {
        detector: "prototype-generation-loop-pictorial-atom-crop",
        layerType: "illustration-zone",
        expressionForm: "icon-or-illustration",
        expressionSubtype: region.key || "prototype-loop-pictorial-atom",
        recommendedAction: "keep-local-crop",
        intentionalMinimumUnitCrop: true,
        protectedMinimumUnit: true,
        skipVisualAtomRebuild: true,
        ...(region.component || {}),
        nonEditableReason: "pictorial icon preserved as the smallest faithful visual unit inside an editable prototype-generation loop"
      })
    };
  });
}





























