  add("document-version-governance-portal-underline", "roundRect", { x: 625, y: 151, w: 170, h: 7 }, { fill: "#8FBDEB", stroke: "none", strokeWidthPt: 0, radiusRatio: 0.4, opacity: 0.9 }, { role: "portal-underline" });
