function addSkillsEngineAiComparisonMatrixText(textBoxes, source, layout) {
  const push = (id, value, box, font = {}, extra = {}) => {
    const textBox = temporaryAnswerWorkflowTextBox(
      `skills-engine-ai-matrix-${id}`,
      value,
      box,
      {
        family: "Microsoft YaHei",
        sizePt: font.sizePt || 16,
        color: font.color || "#111111",
        weight: font.weight || "regular",
        align: font.align || "left",
        valign: "middle"
      },
      source("skills-engine-ai-comparison-native-text", extra)
    );
    if (font.wrap === false) textBox.wrap = false;
    textBoxes.push(textBox);
  };
  const blue = "#0D557A";
  const headers = ["", "传统手工推进", "普通对话式AI", "PM Portal Skills 引擎"];
  headers.forEach((value, col) => {
    if (!value) return;
    push(`header-${col}`, value, {
      x: round(layout.colBounds[col].x + 20),
      y: round(layout.headerY),
      w: round(layout.colBounds[col].w - 40),
      h: 34
    }, { sizePt: col === 3 ? 15.5 : 17.5, color: blue, weight: "bold", align: "center", wrap: false }, { role: "header", col });
  });
  const rows = [
    ["上下文感知", "依赖个人记忆", "无系统/历史知识", "实时挂载全域资产"],
    ["质量校验与拦截", "依赖人工评审", "仅做文字润色", "智能预校验逻辑边界"],
    ["资产落盘", "散落各处", "停留在对话窗", "自动推入标准域仓"]
  ];
  rows.forEach((row, rowIndex) => {
    const y = layout.rowCenters[rowIndex];
    row.forEach((value, col) => {
      const iconPad = col === 1 || col === 2 ? layout.colBounds[col].w * 0.18 : (col === 3 ? layout.colBounds[col].w * 0.11 : 0);
      push(`row-${rowIndex}-col-${col}`, value, {
        x: round(layout.colBounds[col].x + (col === 0 ? 10 : 18)),
        y: round(y - 16),
        w: round(col === 0 ? layout.colBounds[col].w - 14 : layout.colBounds[col].w - (col === 3 ? 24 : 36) - iconPad),
        h: 32
      }, {
        sizePt: col === 0 ? 16.5 : (col === 3 ? 14.2 : 16.5),
        color: col === 0 ? blue : "#111111",
        weight: col === 0 ? "bold" : "regular",
        align: col === 0 ? "left" : "left",
        wrap: col === 0 || col === 3 ? false : undefined
      }, { role: col === 0 ? "row-header" : "cell", row: rowIndex, col });
    });
  });
}

function createWorkflowComparisonMatrixObjects(page = {}, rawTextBoxes = [], slideSize = DEFAULT_SLIDE, sourceImage = null) {
  if (!shouldObjectifyWorkflowComparisonMatrix(page, rawTextBoxes, slideSize)) return { shapes: [], textBoxes: [] };
  for (const image of page.images || []) {
    image.source = {
      ...(image.source || {}),
      workflowComparisonMatrixObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "workflow comparison matrix"}; rebuilt four-column comparison matrix as native editable table component`
    };
  }
  const source = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    confidence: 0.9,
    expressionForm: "comparison-matrix",
    expressionSubtype: "workflow-ai-skills-comparison",
    ...extra
  });
  const shapes = [];
  const textBoxes = [];
  const add = (shape) => shapes.push(shape);
  const table = workflowComparisonMatrixLayout(slideSize, rawTextBoxes);
  addWorkflowComparisonMatrixCells(add, source, table, sourceImage);
  addWorkflowComparisonMatrixChecks(add, source, table, rawTextBoxes);
  addWorkflowComparisonMatrixText(textBoxes, source, table, rawTextBoxes);
  return { shapes, textBoxes };
}

function shouldObjectifyWorkflowComparisonMatrix(page = {}, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const labels = (rawTextBoxes || []).map((item) => normalizeCjkText(item.text)).join(" ");
  if (!/传统工作方式/.test(labels) || !/普通AI工具/.test(labels) || !/PMPortalAISkills/.test(labels)) return false;
  if (!/场景理解/.test(labels) || !/流程引擎/.test(labels) || !/质量控制/.test(labels) || !/资产沉淀/.test(labels)) return false;
  if (!/深度结合真实系统架构与沉淀资产/.test(labels) || !/产出自动落盘为标准分布式域仓资产/.test(labels)) return false;
  const area = Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt);
  return (page.images || []).some((image) => {
    const box = image.box || {};
    const areaRatio = Number(box.w || 0) * Number(box.h || 0) / Math.max(1, area);
    if (areaRatio < 0.45) return false;
    const detector = String(image.source?.detector || image.source?.reason || "");
    return /comparison-matrix|source-background|underlay|full-slide/i.test(detector)
      || image.source?.editable === false;
  }) || rawTextBoxes.length >= 16;
}

function workflowComparisonMatrixLayout(slideSize = DEFAULT_SLIDE, rawTextBoxes = []) {
  const width = Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt);
  const height = Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt);
  const evidence = workflowComparisonMatrixTextEvidence(rawTextBoxes);
  const fallback = {
    x: width * 0.0594,
    y: height * 0.099,
    w: width * 0.8813,
    gap: width * 0.0042,
    headerH: height * 0.0972,
    rowH: height * 0.1713
  };
  const rowCenters = evidence.rows.map((row) => median(row.filter(Boolean).map((item) => boxCenterY(item.box)))).filter(Number.isFinite);
  const rowSteps = rowCenters.slice(1).map((center, index) => center - rowCenters[index]).filter((step) => step > 20);
  const gap = round(clamp(fallback.gap, 3, 6));
  const rowStep = rowSteps.length > 0 ? median(rowSteps) : fallback.rowH + gap;
  const rowH = round(clamp(rowStep - gap, height * 0.14, height * 0.2));
  const headerCenter = evidence.headers.length > 0
    ? median(evidence.headers.map((item) => boxCenterY(item.box)))
    : fallback.y + fallback.headerH / 2;
  const firstRowCenter = rowCenters[0] || (fallback.y + fallback.headerH + gap + rowH / 2);
  const headerH = round(clamp(2 * (firstRowCenter - headerCenter - gap) - rowH, height * 0.075, height * 0.12));
  const rowHeaderBoxes = evidence.rows.map((row) => row[0]).filter(Boolean);
  const portalBoxes = evidence.rows.map((row) => row[3]).filter(Boolean);
  const minRowHeaderX = rowHeaderBoxes.length > 0 ? Math.min(...rowHeaderBoxes.map((item) => Number(item.box?.x || Infinity))) : Infinity;
  const maxPortalRight = portalBoxes.length > 0 ? Math.max(...portalBoxes.map((item) => Number(item.box?.x || 0) + Number(item.box?.w || 0))) : -Infinity;
  const tableX = Number.isFinite(minRowHeaderX) ? minRowHeaderX - width * 0.0174 : fallback.x;
  const tableRight = Number.isFinite(maxPortalRight) ? maxPortalRight + width * 0.016 : fallback.x + fallback.w;
  const table = {
    x: round(clamp(tableX, 0, width - 1)),
    y: round(clamp(headerCenter - headerH / 2, 0, height - 1)),
    w: round(clamp(tableRight - tableX, width * 0.75, width * 0.94)),
    h: round(headerH + gap + 4 * rowH + 3 * gap)
  };
  const availableW = table.w - gap * 3;
  const ratios = [0.1232, 0.2301, 0.2606, 0.3861];
  const colW = ratios.map((ratio) => round(availableW * ratio));
  colW[colW.length - 1] = round(availableW - colW.slice(0, -1).reduce((sum, value) => sum + value, 0));
  const xs = [table.x];
  for (let index = 0; index < colW.length - 1; index += 1) xs.push(xs[index] + colW[index] + gap);
  const ys = [table.y, table.y + headerH + gap];
  for (let index = 1; index < 4; index += 1) ys.push(ys[1] + index * (rowH + gap));
  return { table, gap, headerH, rowH, colW, xs, ys, slideSize, evidence };
}

function addWorkflowComparisonMatrixCells(add, source, layout, sourceImage = null) {
  const { xs, ys, colW, headerH, rowH } = layout;
  const grayHeader = sampleWorkflowMatrixCellFill(sourceImage, { x: xs[1], y: ys[0], w: colW[1], h: headerH }, layout.slideSize, "#C9C9C9");
  const rowHeader = sampleWorkflowMatrixCellFill(sourceImage, { x: xs[0], y: ys[1], w: colW[0], h: rowH }, layout.slideSize, "#E6E6E6");
  const body = sampleWorkflowMatrixCellFill(sourceImage, { x: xs[1], y: ys[1], w: colW[1], h: rowH }, layout.slideSize, "#ECECEC");
  const blue = sampleWorkflowMatrixCellFill(sourceImage, { x: xs[3], y: ys[1], w: colW[3], h: rowH }, layout.slideSize, "#005EB8");
  const stroke = "#FFFFFF";
  for (let col = 1; col < 4; col += 1) {
    add({
      id: `workflow-comparison-header-${col}`,
      type: "rect",
      box: { x: xs[col], y: ys[0], w: colW[col], h: headerH },
      style: { fill: col === 3 ? blue : grayHeader, stroke, strokeWidthPt: 1 },
      source: source("workflow-comparison-matrix-native-cell", { role: "header", col })
    });
  }
  for (let row = 0; row < 4; row += 1) {
    for (let col = 0; col < 4; col += 1) {
      add({
        id: `workflow-comparison-cell-${row}-${col}`,
        type: "rect",
        box: { x: xs[col], y: ys[row + 1], w: colW[col], h: rowH },
        style: { fill: col === 3 ? blue : (col === 0 ? rowHeader : body), stroke, strokeWidthPt: 1 },
        source: source("workflow-comparison-matrix-native-cell", { role: col === 0 ? "row-header" : "body", row, col })
      });
    }
  }
}

function addWorkflowComparisonMatrixChecks(add, source, layout, rawTextBoxes = []) {
  const { xs, ys, colW, rowH } = layout;
  const evidence = workflowComparisonMatrixTextEvidence(rawTextBoxes);
  for (let row = 0; row < 4; row += 1) {
    const portalText = evidence.rows[row]?.[3];
    const cx = portalText ? Number(portalText.box.x) - 17 : xs[3] + 31;
    const cy = portalText ? boxCenterY(portalText.box) : ys[row + 1] + rowH / 2;
    const size = 24;
    add({ id: `workflow-comparison-check-bg-${row}`, type: "rect", box: { x: cx - size / 2, y: cy - size / 2, w: size, h: size }, style: { fill: "#28A946", stroke: "#1E8F3A", strokeWidthPt: 0.8, radiusPt: 4, shadow: { color: "#095C2B", alpha: 0.18, blurPt: 2, distancePt: 1, angle: 45 } }, source: source("workflow-comparison-matrix-native-check", { row, part: "bg" }) });
    add({ id: `workflow-comparison-check-a-${row}`, type: "line", box: lineBox({ x: cx - 7, y: cy - 1 }, { x: cx - 2, y: cy + 6 }), style: { stroke: "#FFFFFF", strokeWidthPt: 2.6, connectorType: "straight", lineCap: "round" }, source: source("workflow-comparison-matrix-native-check-mark", { row, part: "a" }) });
    add({ id: `workflow-comparison-check-b-${row}`, type: "line", box: lineBox({ x: cx - 2, y: cy + 6 }, { x: cx + 8, y: cy - 8 }), style: { stroke: "#FFFFFF", strokeWidthPt: 2.6, connectorType: "straight", lineCap: "round" }, source: source("workflow-comparison-matrix-native-check-mark", { row, part: "b" }) });
  }
  add({ id: "workflow-comparison-blue-column-highlight", type: "rect", box: { x: xs[3], y: ys[1], w: colW[3], h: ys[4] + rowH - ys[1] }, style: { fill: "none", stroke: "#004D9C", strokeWidthPt: 1.3 }, source: source("workflow-comparison-matrix-native-blue-column-outline") });
}

function addWorkflowComparisonMatrixText(textBoxes, source, layout, rawTextBoxes = []) {
  const { xs, ys, colW, headerH, rowH } = layout;
  const evidence = workflowComparisonMatrixTextEvidence(rawTextBoxes);
  const text = (id, value, box, font = {}, extra = {}) => textBoxes.push(temporaryAnswerWorkflowTextBox(
    `workflow-comparison-${id}`,
    value,
    box,
    {
      family: "Microsoft YaHei",
      sizePt: font.sizePt || 18,
      color: font.color || "#111111",
      weight: font.weight || "regular",
      align: font.align || "center",
      valign: "middle"
    },
    source("workflow-comparison-matrix-native-text", extra)
  ));
  const headers = ["", "传统工作方式", "普通 AI 工具", "PM Portal AI Skills"];
  headers.forEach((value, col) => {
    if (!value) return;
    const measured = evidence.headers[col - 1];
    text(`header-${col}`, value, workflowComparisonMeasuredTextBox(measured, { x: xs[col] + 10, y: ys[0] + 10, w: colW[col] - 20, h: headerH - 20 }), {
      sizePt: workflowComparisonMeasuredFontSize(measured, col === 3 ? 22 : 20),
      color: col === 3 ? "#FFFFFF" : "#555555",
      weight: "bold"
    }, { role: "header", col });
  });
  const rows = [
    ["场景理解", "人工翻阅大量历史材料", "缺少公司上下文与域仓目录", "深度结合真实系统架构与沉淀资产"],
    ["流程引擎", "手动推进各断裂环节", "碎片化、一次性的临时问答", "需求→PRD→评审→原型无缝串联"],
    ["质量控制", "依赖评审会人工纠错", "仅生成文字，缺乏严谨逻辑校验", "前置拦截风险，强制扫描完整性"],
    ["资产沉淀", "结果散落个人电脑各处", "会话结束数据即刻丢失", "产出自动落盘为标准分布式域仓资产"]
  ];
  rows.forEach((row, rowIndex) => {
    row.forEach((value, col) => {
      const isPortal = col === 3;
      const isRowHeader = col === 0;
      const leftPad = isPortal ? 68 : (isRowHeader ? 0 : 12);
      const measured = evidence.rows[rowIndex]?.[col];
      text(`row-${rowIndex}-col-${col}`, value, workflowComparisonMeasuredTextBox(measured, {
        x: xs[col] + leftPad,
        y: ys[rowIndex + 1] + 31,
        w: colW[col] - leftPad - 12,
        h: rowH - 58
      }), {
        sizePt: workflowComparisonMeasuredFontSize(measured, isPortal ? 14.2 : (isRowHeader ? 18.5 : 16.5)),
        color: isPortal ? "#FFFFFF" : (isRowHeader ? "#5E5E5E" : "#111111"),
        weight: isPortal || isRowHeader ? "bold" : "regular",
        align: isRowHeader ? "center" : "left"
      }, { role: isRowHeader ? "row-header" : "cell", row: rowIndex, col });
    });
  });
}

function workflowComparisonMatrixTextEvidence(rawTextBoxes = []) {
  const find = (value) => rawTextBoxes.find((item) => normalizeCjkText(item.text) === normalizeCjkText(value)) || null;
  const headers = ["传统工作方式", "普通AI工具", "PMPortalAISkills"].map(find).filter(Boolean);
  const rows = [
    ["场景理解", "人工翻阅大量历史材料", "缺少公司上下文与域仓目录", "深度结合真实系统架构与沉淀资产"],
    ["流程引擎", "手动推进各断裂环节", "碎片化、一次性的临时问答", "需求→PRD→评审→原型无缝串联"],
    ["质量控制", "依赖评审会人工纠错", "仅生成文字，缺乏严谨逻辑校验", "前置拦截风险，强制扫描完整性"],
    ["资产沉淀", "结果散落个人电脑各处", "会话结束数据即刻丢失", "产出自动落盘为标准分布式域仓资产"]
  ].map((row) => row.map(find));
  return { headers, rows };
}

function workflowComparisonMeasuredTextBox(item, fallback) {
  if (!item?.box) return fallback;
  return {
    x: round(Number(item.box.x || 0) - 1.5),
    y: round(Number(item.box.y || 0) - 1.5),
    w: round(Number(item.box.w || 0) + 3),
    h: round(Number(item.box.h || 0) + 3)
  };
}

function workflowComparisonMeasuredFontSize(item, fallback) {
  return measuredFontSize(item, fallback, { minimum: 7, maximum: 400 });
}

function sampleWorkflowMatrixCellFill(sourceImage, ptBox, slideSize, fallback) {
  if (!sourceImage?.rgba || !sourceImage.width || !sourceImage.height) return fallback;
  const box = ptToPxBox(ptBox, sourceImage, slideSize, 0);
  const insetX = Math.max(2, Math.round(box.w * 0.08));
  const insetY = Math.max(2, Math.round(box.h * 0.12));
  const buckets = new Map();
  const step = Math.max(1, Math.ceil(Math.sqrt((box.w * box.h) / 1600)));
  for (let y = box.y + insetY; y < box.y + box.h - insetY; y += step) {
    for (let x = box.x + insetX; x < box.x + box.w - insetX; x += step) {
      const color = pixel(sourceImage, x, y);
      if (color.a < 64) continue;
      const key = `${Math.round(color.r / 8)},${Math.round(color.g / 8)},${Math.round(color.b / 8)}`;
      const value = buckets.get(key) || { count: 0, r: 0, g: 0, b: 0 };
      value.count += 1;
      value.r += color.r;
      value.g += color.g;
      value.b += color.b;
      buckets.set(key, value);
    }
  }
  const dominant = [...buckets.values()].sort((a, b) => b.count - a.count)[0];
  if (!dominant || dominant.count < 4) return fallback;
  return rgbToHex({
    r: Math.round(dominant.r / dominant.count),
    g: Math.round(dominant.g / dominant.count),
    b: Math.round(dominant.b / dominant.count)
  });
}

function createWorkflowCollaborationMultiplierObjects(page = {}, rawTextBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  if (!shouldObjectifyWorkflowCollaborationMultiplier(page, rawTextBoxes, slideSize)) return { shapes: [], textBoxes: [] };
  for (const image of page.images || []) {
    image.source = {
      ...(image.source || {}),
      workflowCollaborationMultiplierObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "workflow collaboration multiplier"}; rebuilt hub-and-branch collaboration diagram as native editable component`
    };
  }
  const source = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    confidence: 0.88,
    expressionForm: "hub-and-branch-diagram",
    expressionSubtype: "workflow-collaboration-multiplier",
    ...extra
  });
  let shapes = [];
  const textBoxes = [];
  const add = (shape) => shapes.push(shape);
  // This diagram has a measured cubic route implementation. Keep only the
  // four authored pictorial icons as crops; the hub, branches, and cards stay
  // native by default. A caller can still explicitly preserve the full left
  // illustration when visual validation says the source is too irregular.
  const leftGraphicCrop = options.preserveWorkflowCollaborationGraphic === true
    ? createWorkflowCollaborationMultiplierGraphicCrop(page, slideSize, options)
    : null;
  const iconCrops = createWorkflowCollaborationIconCrops(page, slideSize, {
    ...options,
    includeHub: !leftGraphicCrop
  });
  const measuredBranches = measureWorkflowCollaborationBranches(page, slideSize);
  if (leftGraphicCrop) page.images.push(leftGraphicCrop);
  if (iconCrops.length > 0) page.images.push(...iconCrops);
  addWorkflowCollaborationTitle(add, textBoxes, source);
  if (!leftGraphicCrop) {
    addWorkflowCollaborationBranches(add, source, measuredBranches);
    addWorkflowCollaborationHub(add, textBoxes, source, iconCrops.length > 0);
  }
  addWorkflowCollaborationCards(add, textBoxes, source, iconCrops.length > 0);
  addWorkflowCollaborationBottomBanner(add, textBoxes, source, slideSize);
  return { shapes, textBoxes };
}

function measureWorkflowCollaborationBranches(page = {}, slideSize = DEFAULT_SLIDE) {
  const sourceImageFile = page.sourceImage;
  if (!sourceImageFile || !fs.existsSync(sourceImageFile)) return null;
  const result = measureBranchCurvesFromAnchors(readPng(sourceImageFile), {
    slideSize,
    sourceBox: { x: 96, y: 216, w: 148, h: 148 },
    targetBoxes: workflowCollaborationCards().map((card) => ({ x: 448, y: card.y, w: 482, h: 103 })),
    sampleCount: 11,
    searchRadiusPt: 58,
    minimumCoverage: 0.72
  });
  return result.ok && result.confidence >= 0.72
    ? {
      ...result,
      curves: result.curves.map((curve) => ({
        ...curve,
        routeColor: result.routeColor,
        routeColorMode: result.routeColorMode,
        routeColorConfidence: result.routeColorConfidence
      }))
    }
    : null;
}

function createWorkflowCollaborationIconCrops(page = {}, slideSize = DEFAULT_SLIDE, options = {}) {
  const sourceImageFile = page.sourceImage || options.sourceImage;
  if (!sourceImageFile || !fs.existsSync(sourceImageFile)) return [];
  const deckName = options.deckName || "deck";
  const pageNumber = Number.isFinite(Number(options.pageIndex))
    ? Number(options.pageIndex) + 1
    : Number(page.pageIndex || 0) + 1;
  const assetDir = options.assetDir || (options.irDir ? path.join(options.irDir, `${deckName}.assets`) : null);
  if (!assetDir) return [];
  const sourceImage = readPng(sourceImageFile);
  const units = [
    { key: "hub", box: { x: 137, y: 217, w: 67, h: 59 }, subtype: "processor-chip-icon" },
    { key: "be", box: { x: 468, y: 113, w: 80, h: 80 }, subtype: "database-server-icon" },
    { key: "fe", box: { x: 468, y: 237, w: 80, h: 80 }, subtype: "browser-window-icon" },
    { key: "qa", box: { x: 468, y: 360, w: 82, h: 88 }, subtype: "qa-checklist-icon" }
  ];
  ensureDir(assetDir);
  return units
    .filter((unit) => options.includeHub !== false || unit.key !== "hub")
    .map((unit) => {
    const fileName = `${deckName}-p${String(pageNumber).padStart(2, "0")}-workflow-collab-${unit.key}-icon.png`;
    const cropped = cropPng(sourceImage, ptToPxBox(unit.box, sourceImage, slideSize, 0));
    const isolated = unit.key === "hub"
      ? makeEdgeConnectedBackgroundTransparent(cropped, { transparentDistance: 12, maximumDistance: 68 })
      : cropped;
    writePng(path.join(assetDir, fileName), isolated);
    return {
      id: `workflow-collab-${unit.key}-icon-crop`,
      type: "fidelity-crop",
      assetPath: `${deckName}.assets/${fileName}`,
      box: unit.box,
      source: {
        editable: false,
        detector: "workflow-collab-icon-minimum-unit-crop",
        confidence: 0.94,
        expressionForm: "icon-or-illustration",
        expressionSubtype: unit.subtype,
        strategy: "minimum-visual-unit-crop",
        recommendedAction: "match-icon-library-or-keep-local-crop",
        skipVisualAtomRebuild: true,
        nonEditableReason: "complex pictorial icon preserved as one minimum visual unit while its card, text, and connecting route remain native editable"
      }
    };
    });
}

function createWorkflowCollaborationMultiplierGraphicCrop(page = {}, slideSize = DEFAULT_SLIDE, options = {}) {
  const sourceImageFile = page.sourceImage || options.sourceImage;
  if (!sourceImageFile || !fs.existsSync(sourceImageFile)) return null;
  const deckName = options.deckName || "deck";
  const pageNumber = Number.isFinite(Number(options.pageIndex))
    ? Number(options.pageIndex) + 1
    : Number(page.pageIndex || 0) + 1;
  const assetDir = options.assetDir || (options.irDir ? path.join(options.irDir, `${deckName}.assets`) : null);
  if (!assetDir) return null;
  const sourceImage = readPng(sourceImageFile);
  // Stop at the card edge so the crop cannot reintroduce card text or chrome.
  const cropBox = { x: 36, y: 145, w: 412, h: 300 };
  const pxBox = ptToPxBox(cropBox, sourceImage, slideSize, 0);
  ensureDir(assetDir);
  const fileName = `${deckName}-p${String(pageNumber).padStart(2, "0")}-workflow-collab-left-graphic.png`;
  const file = path.join(assetDir, fileName);
  writePng(file, cropPng(sourceImage, pxBox));
  return {
    id: "workflow-collab-left-graphic-crop",
    type: "fidelity-crop",
    assetPath: `${deckName}.assets/${fileName}`,
    box: cropBox,
    source: {
      editable: false,
      detector: "workflow-collab-left-graphic-crop",
      reason: "hub-and-curved-branches-preserved-as-local-component-crop",
      strategy: "local-fidelity-crop",
      expressionForm: "hub-and-branch-diagram",
      expressionSubtype: "workflow-collaboration-multiplier-left-graphic",
      recommendedAction: "preserve-local-crop",
      skipVisualAtomRebuild: true,
      nonEditableReason: "PM Skills hub and curved branch graphic preserved as a local crop because the current OpenXML generator only supports straight/elbow connectors; right cards and banner remain native editable"
    }
  };
}

function createWorkflowCollaborationCardBackgroundCrop(page = {}, nativeTextBoxes = [], rawTextBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  const sourceImageFile = page.sourceImage || options.sourceImage;
  if (!sourceImageFile || !fs.existsSync(sourceImageFile)) return null;
  const deckName = options.deckName || "deck";
  const pageNumber = Number.isFinite(Number(options.pageIndex))
    ? Number(options.pageIndex) + 1
    : Number(page.pageIndex || 0) + 1;
  const assetDir = options.assetDir || (options.irDir ? path.join(options.irDir, `${deckName}.assets`) : null);
  if (!assetDir) return null;
  const sourceImage = readPng(sourceImageFile);
  const cardRegion = { x: 448, y: 96, w: 482, h: 356 };
  const nativeMasks = (nativeTextBoxes || [])
    .filter((textBox) => textBox?.source?.role === "card-title" || textBox?.source?.role === "card-body")
    .map((textBox) => ptToPxBox(expandPtBox(textBox.box, slideSize, 9, 7), sourceImage, slideSize, 0));
  const rawMasks = (rawTextBoxes || [])
    .filter((textBox) => boxCenterInside(textBox.box, cardRegion))
    .map((textBox) => ptToPxBox(expandPtBox(textBox.box, slideSize, 8, 6), sourceImage, slideSize, 0));
  const textMasks = [...nativeMasks, ...rawMasks];
  const erased = textMasks.length > 0 ? eraseMasks(sourceImage, textMasks) : sourceImage;
  const crop = cropPng(erased, ptToPxBox(cardRegion, sourceImage, slideSize, 0));
  ensureDir(assetDir);
  const fileName = `${deckName}-p${String(pageNumber).padStart(2, "0")}-workflow-collab-card-backgrounds.png`;
  const file = path.join(assetDir, fileName);
  writePng(file, crop);
  return {
    id: "workflow-collab-card-backgrounds-crop",
    type: "fidelity-crop",
    assetPath: `${deckName}.assets/${fileName}`,
    box: cardRegion,
    source: {
      editable: false,
      detector: "workflow-collab-card-backgrounds-crop",
      reason: "right-card-backgrounds-icons-shadows-preserved-with-text-erased",
      strategy: "local-fidelity-crop",
      expressionForm: "card-stack-component",
      expressionSubtype: "workflow-collaboration-multiplier-card-backgrounds",
      recommendedAction: "keep-local-crop-and-overlay-external-text-only",
      skipVisualAtomRebuild: true,
      textErasedFromCrop: textMasks.length > 0,
      nonEditableReason: "right card chrome, icons, shadows, and accents preserved as a text-erased local crop while titles and descriptions remain native editable text"
    }
  };
}

function isWorkflowCollaborationCardChromeShape(shape = {}) {
  const detector = String(shape.source?.detector || "");
  return detector === "workflow-collab-multiplier-native-card-shadow"
    || detector === "workflow-collab-multiplier-native-card"
    || detector === "workflow-collab-multiplier-native-card-accent"
    || detector === "workflow-collab-multiplier-native-card-icon"
    || detector === "workflow-collab-multiplier-native-card-icon-detail";
}

function markWorkflowCollaborationCardTextAsErasedOverlay(textBoxes = [], cardBackground = {}) {
  for (const textBox of textBoxes || []) {
    const role = textBox?.source?.role;
    if (role !== "card-title" && role !== "card-body") continue;
    textBox.source = {
      ...(textBox.source || {}),
      layerSourceId: cardBackground.id,
      textErasedFromCrop: true
    };
  }
}

function shouldObjectifyWorkflowCollaborationMultiplier(page = {}, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const labels = (rawTextBoxes || []).map((item) => normalizeCjkText(item.text)).join(" ");
  if (!/协同倍增器/.test(labels) || !/下游研发视角/.test(labels)) return false;
  if (!/PMSkills/.test(labels) || !/处理引擎/.test(labels)) return false;
  const roleHits = [/To后端研发BE/, /To前端研发FE/, /To测试QA/].filter((pattern) => pattern.test(labels)).length;
  if (roleHits < 3) return false;
  if (!/研发返工率大幅降低/.test(labels) || !/全链路降本/.test(labels)) return false;
  const slideArea = Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt);
  const hasUsefulRaster = (page.images || []).some((image) => {
    const box = image.box || {};
    const areaRatio = Number(box.w || 0) * Number(box.h || 0) / Math.max(1, slideArea);
    const detector = String(image.source?.detector || image.source?.reason || "");
    return areaRatio > 0.2 || /collaboration-flow|source-background|underlay|full-slide/i.test(detector);
  });
  return hasUsefulRaster || rawTextBoxes.length >= 12;
}

